package com.shopstream.gateway;

import java.time.Duration;
import java.time.Instant;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class FixedWindowLimiter {

    private static final long WINDOW_SECONDS = 60;
    private final StringRedisTemplate redis;

    public FixedWindowLimiter(StringRedisTemplate redis) {
        this.redis = redis;
    }

    public boolean allow(String ip, String route, long limit) {
        long window = Instant.now().getEpochSecond() / WINDOW_SECONDS;
        String key = "rl:" + ip + ":" + route + ":" + window;
        Long count = redis.opsForValue().increment(key);
        if (count != null && count == 1L) {
            redis.expire(key, Duration.ofSeconds(WINDOW_SECONDS));
        }
        return count != null && count <= limit;
    }
}
